window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["shopify"]={html:"<div class=\"own-shopify\">\n  <!-- ── NAV (cinematic, over hero) ──────────────────────────────────── -->\n  <header class=\"sh-nav\">\n    <a class=\"sh-brand\" href=\"#sh-top\" aria-label=\"Northwind home\">Northwind</a>\n    <nav class=\"sh-nav-links\" aria-label=\"Primary\">\n      <a href=\"#sh-features\">Product</a>\n      <a href=\"#sh-regions\">Regions</a>\n      <a href=\"#sh-pricing\">Pricing</a>\n      <a href=\"#sh-customers\">Customers</a>\n    </nav>\n    <div class=\"sh-nav-right\">\n      <a class=\"sh-pill sh-pill-ghost\" href=\"#\">Log in</a>\n      <a class=\"sh-pill sh-pill-ghost\" href=\"#sh-pricing\">Start free trial</a>\n    </div>\n  </header>\n\n  <main id=\"sh-top\">\n    <!-- ── CINEMATIC HERO ────────────────────────────────────────────── -->\n    <section class=\"sh-hero\" aria-labelledby=\"sh-h1\">\n      <div class=\"sh-hero-vis\" aria-hidden=\"true\">\n        <div class=\"sh-hero-glow\"></div>\n        <div class=\"sh-hero-grid\"></div>\n        <div class=\"sh-hero-panel\">\n          <div class=\"sh-hp-head\"><span class=\"sh-hp-title\">Regional throughput</span><span class=\"sh-hp-badge\">Live</span></div>\n          <div class=\"sh-hp-bars\"><span style=\"--h:54%\"></span><span style=\"--h:78%\"></span><span style=\"--h:46%\"></span><span style=\"--h:90%\"></span><span style=\"--h:66%\"></span><span style=\"--h:82%\"></span><span style=\"--h:58%\"></span></div>\n          <div class=\"sh-hp-foot\"><span>Luzon</span><span>Visayas</span><span>Mindanao</span></div>\n        </div>\n      </div>\n      <div class=\"sh-hero-copy\">\n        <h1 id=\"sh-h1\" class=\"sh-display\">Run every region<br>on one operating floor.</h1>\n        <p class=\"sh-hero-sub\">Northwind gives operations teams a single control room for throughput, cost, and yield — across every site, in real time.</p>\n        <a class=\"sh-pill sh-pill-outline\" href=\"#sh-pricing\">Start free trial</a>\n      </div>\n    </section>\n\n    <!-- ── STATEMENT BAND ────────────────────────────────────────────── -->\n    <section class=\"sh-statement\">\n      <p class=\"sh-statement-text\">One platform. Every region. <span class=\"sh-dim\">No spreadsheets.</span></p>\n    </section>\n\n    <!-- ── FEATURE ROWS (cinematic dark) ─────────────────────────────── -->\n    <section id=\"sh-features\" class=\"sh-band\">\n      <p class=\"sh-eyebrow\">What operations teams get</p>\n      <h2 class=\"sh-display-lg\">Built for the floor,<br>not the boardroom.</h2>\n      <div class=\"sh-features\" id=\"shFeatureGrid\"></div>\n    </section>\n\n    <!-- ── REGIONS BAND ──────────────────────────────────────────────── -->\n    <section id=\"sh-regions\" class=\"sh-band\">\n      <div class=\"sh-regions\">\n        <div class=\"sh-regions-copy\">\n          <p class=\"sh-eyebrow\">Global by default</p>\n          <h2 class=\"sh-display-lg\">42 regions.<br>One truth.</h2>\n          <p class=\"sh-body sh-dim\">Roll up site-level metrics into a regional view with a single query. Currency, timezone, and unit conversion handled for you.</p>\n        </div>\n        <ul class=\"sh-region-list\" id=\"shRegionList\"></ul>\n      </div>\n    </section>\n\n    <!-- ── LIGHT / TRANSACTIONAL TRACK ───────────────────────────────── -->\n    <section id=\"sh-pricing\" class=\"sh-light\">\n      <div class=\"sh-light-head\">\n        <p class=\"sh-eyebrow sh-on-light\">Pricing</p>\n        <h2 class=\"sh-display-lg sh-on-light\">Plans that scale<br>with your floor.</h2>\n        <p class=\"sh-body sh-on-light-mute\">Start free. Upgrade when your operations outgrow the basics.</p>\n      </div>\n      <div class=\"sh-tiers\" id=\"shTierGrid\"></div>\n\n      <!-- pistachio band -->\n      <div class=\"sh-band-card\">\n        <div>\n          <span class=\"sh-tag sh-tag-mint\">Add-on</span>\n          <h3 class=\"sh-display-md\">Northwind Forecast</h3>\n          <p class=\"sh-body\">Predict next quarter's throughput per region with confidence intervals tuned to your seasonality.</p>\n        </div>\n        <a class=\"sh-pill sh-pill-dark\" href=\"#\">Add to plan</a>\n      </div>\n\n      <!-- comparison table -->\n      <div class=\"sh-compare\" role=\"table\" aria-label=\"Plan comparison\">\n        <div class=\"sh-cmp-row sh-cmp-head\" role=\"row\"><span role=\"columnheader\">Feature</span><span role=\"columnheader\">Team</span><span role=\"columnheader\">Business</span><span role=\"columnheader\">Enterprise</span></div>\n        <div class=\"sh-cmp-row\" role=\"row\"><span role=\"cell\">Live dashboards</span><span role=\"cell\">Unlimited</span><span role=\"cell\">Unlimited</span><span role=\"cell\">Unlimited</span></div>\n        <div class=\"sh-cmp-row\" role=\"row\"><span role=\"cell\">Regions</span><span role=\"cell\">3</span><span role=\"cell\">25</span><span role=\"cell\">Unlimited</span></div>\n        <div class=\"sh-cmp-row\" role=\"row\"><span role=\"cell\">Forecast add-on</span><span role=\"cell\">—</span><span role=\"cell\">Included</span><span role=\"cell\">Included</span></div>\n        <div class=\"sh-cmp-row\" role=\"row\"><span role=\"cell\">SSO &amp; audit log</span><span role=\"cell\">—</span><span role=\"cell\">Yes</span><span role=\"cell\">Yes</span></div>\n      </div>\n    </section>\n\n    <!-- ── LOGO WALL ─────────────────────────────────────────────────── -->\n    <section id=\"sh-customers\" class=\"sh-band sh-logos\">\n      <div class=\"sh-logo-wall\" aria-label=\"Customers\">\n        <span>ATLAS</span><span>KESTREL</span><span>MERIDIAN</span><span>HELIOS</span><span>NORTHFORK</span><span>BLUEPRINT</span>\n      </div>\n    </section>\n  </main>\n\n  <!-- ── FOOTER (dark) ───────────────────────────────────────────────── -->\n  <footer class=\"sh-footer\">\n    <div class=\"sh-foot-grid\">\n      <div class=\"sh-foot-brand\">\n        <span class=\"sh-brand\">Northwind</span>\n        <p class=\"sh-caption\">Operations analytics for teams that run the floor.</p>\n      </div>\n      <div class=\"sh-foot-col\"><h3>Product</h3><a href=\"#\">Dashboards</a><a href=\"#\">Forecast</a><a href=\"#\">Regions</a></div>\n      <div class=\"sh-foot-col\"><h3>Developers</h3><a href=\"#\">API</a><a href=\"#\">Docs</a><a href=\"#\">Status</a></div>\n      <div class=\"sh-foot-col\"><h3>Company</h3><a href=\"#\">About</a><a href=\"#\">Careers</a><a href=\"#\">Contact</a></div>\n    </div>\n    <div class=\"sh-foot-row\"><span>Sample data — showcase only</span><span>© 2026 Northwind</span></div>\n  </footer>\n</div>\n",css:"/* ══ SHOPIFY — own layout for showcase.html ══════════════════════════════\n   Two-track system: cinematic black canvas with full-bleed product visuals and\n   thin Neue-Haas-style display type, then a cream-mint transactional canvas\n   with aloe/pistachio accents. Pill buttons only, Inter body, ss03 unifier.\n   Scoped under `.own-shopify`. */\n\n.own-shopify {\n  --primary: #000000;\n  --ink: #000000;\n  --on-primary: #ffffff;\n  --canvas-night: #000000;\n  --canvas-night-elev: #0a0a0a;\n  --surface-dark: #1e2c31;\n  --canvas-light: #ffffff;\n  --canvas-cream: #fbfbf5;\n  --shade-30: #d4d4d8;\n  --shade-40: #a1a1aa;\n  --shade-50: #71717a;\n  --shade-60: #52525b;\n  --shade-70: #3f3f46;\n  --hairline-light: #e4e4e7;\n  --hairline-dark: #1e2c31;\n  --aloe: #c1fbd4;\n  --pistachio: #d4f9e0;\n  --link-cool: #9dabad;\n\n  --f-display: 'NeueHaasGrotesk Display', 'Helvetica Neue', Helvetica, Arial, sans-serif;\n  --f-ui: 'Inter Variable', 'Inter', Helvetica, Arial, sans-serif;\n\n  --gut: clamp(20px, 4.6cqi, 72px);\n  --sec: clamp(64px, 10cqi, 128px);\n\n  position: relative;\n  border-radius: 13px;\n  background: var(--canvas-night);\n  color: var(--on-primary);\n  font-family: var(--f-ui);\n  font-variant-numeric: tabular-nums;\n  font-size: 16px;\n  line-height: 1.5;\n  text-align: left;\n  overflow-x: clip;\n  -webkit-font-smoothing: antialiased;\n}\n.own-shopify *, .own-shopify *::before, .own-shopify *::after { box-sizing: border-box; font-feature-settings: \"ss03\"; }\n.own-shopify :focus-visible { outline: 2px solid currentColor; outline-offset: 3px; border-radius: 6px; }\n\n/* ── type ────────────────────────────────────────────────────────────── */\n.own-shopify .sh-display {\n  font-family: var(--f-display); font-weight: 330;\n  font-size: clamp(40px, 7.6cqi, 96px); line-height: 1.0; letter-spacing: 0.025em;\n  margin: 0; max-width: 15ch;\n}\n.own-shopify .sh-display-lg {\n  font-family: var(--f-display); font-weight: 330;\n  font-size: clamp(30px, 4.4cqi, 70px); line-height: 1.02; letter-spacing: 0.01em; margin: 0 0 22px;\n}\n.own-shopify .sh-display-md {\n  font-family: var(--f-display); font-weight: 330;\n  font-size: clamp(24px, 3cqi, 48px); line-height: 1.14; margin: 0 0 12px;\n}\n.own-shopify .sh-eyebrow { font-size: 12px; font-weight: 400; text-transform: uppercase; letter-spacing: 0.72px; color: var(--shade-40); margin: 0 0 20px; }\n.own-shopify .sh-body { font-size: 16px; font-weight: 420; line-height: 1.5; max-width: 60ch; }\n.own-shopify .sh-caption { font-size: 14px; font-weight: 500; letter-spacing: 0.28px; color: var(--shade-40); }\n.own-shopify .sh-dim { color: var(--shade-40); }\n.own-shopify .sh-on-light { color: var(--ink); }\n.own-shopify .sh-on-light-mute { color: var(--shade-50); }\n\n/* ── pills ───────────────────────────────────────────────────────────── */\n.own-shopify .sh-pill {\n  display: inline-flex; align-items: center; justify-content: center;\n  height: 44px; padding: 0 24px; border-radius: 9999px;\n  font-family: var(--f-ui); font-size: 16px; font-weight: 420; line-height: 1;\n  transition: background-color .2s, color .2s, border-color .2s;\n  white-space: nowrap;\n}\n.own-shopify .sh-pill-outline { background: transparent; color: #fff; border: 2px solid #fff; }\n.own-shopify .sh-pill-outline:hover { background: #fff; color: #000; }\n.own-shopify .sh-pill-ghost { background: transparent; color: #fff; border: 1px solid rgba(255,255,255,.5); }\n.own-shopify .sh-pill-ghost:hover { border-color: #fff; background: rgba(255,255,255,.08); }\n.own-shopify .sh-pill-dark { background: #000; color: #fff; }\n.own-shopify .sh-pill-dark:hover { background: var(--shade-70); }\n.own-shopify .sh-pill-mint { background: var(--aloe); color: #000; }\n.own-shopify .sh-pill-mint:hover { background: #a9f4c2; }\n\n/* ── nav ─────────────────────────────────────────────────────────────── */\n.own-shopify .sh-nav {\n  position: sticky; top: 68px; z-index: 40;\n  display: flex; align-items: center; gap: 26px;\n  height: 68px; padding: 0 var(--gut);\n  background: rgba(0,0,0,.72); backdrop-filter: blur(12px);\n}\n.own-shopify .sh-brand { font-family: var(--f-display); font-weight: 500; font-size: 22px; letter-spacing: 0.02em; color: #fff; }\n.own-shopify .sh-nav-links { display: flex; align-items: center; gap: 24px; font-size: 16px; font-weight: 500; }\n.own-shopify .sh-nav-links a { color: rgba(255,255,255,.82); transition: color .18s; }\n.own-shopify .sh-nav-links a:hover { color: #fff; }\n.own-shopify .sh-nav-right { margin-left: auto; display: flex; align-items: center; gap: 12px; }\n.own-shopify .sh-nav-right .sh-pill { height: 40px; font-size: 15px; }\n\n/* ── cinematic hero ──────────────────────────────────────────────────── */\n.own-shopify .sh-hero {\n  position: relative; overflow: hidden; isolation: isolate;\n  min-height: min(760px, calc(100vh - 80px));\n  display: grid; grid-template-columns: 1.05fr .95fr; gap: clamp(24px, 4cqi, 64px);\n  align-items: center;\n  padding: clamp(72px, 12cqi, 160px) var(--gut) clamp(64px, 8cqi, 110px);\n  background: radial-gradient(120% 100% at 82% 12%, #14262b 0%, #050708 48%, #000 100%);\n}\n.own-shopify .sh-hero-vis { position: relative; min-height: 340px; }\n.own-shopify .sh-hero-glow { position: absolute; inset: -10% -6%; background: radial-gradient(50% 50% at 60% 40%, rgba(193,251,212,.16), transparent 70%); }\n.own-shopify .sh-hero-grid {\n  position: absolute; inset: 0; opacity: .35;\n  background-image: linear-gradient(rgba(255,255,255,.07) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,.07) 1px, transparent 1px);\n  background-size: 46px 46px;\n  mask-image: radial-gradient(70% 70% at 50% 50%, #000 40%, transparent 100%);\n}\n.own-shopify .sh-hero-panel {\n  position: relative; z-index: 1;\n  background: rgba(10,10,10,.78); border: 1px solid rgba(255,255,255,.1);\n  border-radius: 20px; padding: 26px; backdrop-filter: blur(4px);\n  box-shadow: 0 25px 50px -12px rgba(0,0,0,.6);\n}\n.own-shopify .sh-hp-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 22px; }\n.own-shopify .sh-hp-title { font-family: var(--f-display); font-weight: 500; font-size: 18px; }\n.own-shopify .sh-hp-badge { font-size: 12px; font-weight: 500; letter-spacing: 0.28px; color: var(--aloe); border: 1px solid rgba(193,251,212,.4); border-radius: 9999px; padding: 3px 10px; }\n.own-shopify .sh-hp-bars { display: flex; align-items: flex-end; gap: clamp(6px, 1.4cqi, 16px); height: 160px; }\n.own-shopify .sh-hp-bars span { flex: 1; height: var(--h); background: linear-gradient(180deg, #fff, var(--aloe)); border-radius: 4px 4px 0 0; }\n.own-shopify .sh-hp-foot { display: flex; justify-content: space-between; margin-top: 14px; font-size: 12px; color: var(--shade-40); }\n.own-shopify .sh-hero-copy { max-width: 620px; }\n.own-shopify .sh-hero-sub { margin: 26px 0 34px; max-width: 46ch; color: rgba(255,255,255,.72); font-size: 18px; font-weight: 550; line-height: 1.56; }\n\n/* ── statement ───────────────────────────────────────────────────────── */\n.own-shopify .sh-statement { padding: clamp(40px, 6cqi, 80px) var(--gut); border-top: 1px solid rgba(255,255,255,.08); border-bottom: 1px solid rgba(255,255,255,.08); }\n.own-shopify .sh-statement-text { font-family: var(--f-display); font-weight: 330; font-size: clamp(24px, 3.4cqi, 48px); line-height: 1.16; margin: 0; }\n\n/* ── dark band ───────────────────────────────────────────────────────── */\n.own-shopify .sh-band { padding: var(--sec) var(--gut) 0; }\n.own-shopify .sh-features { display: grid; gap: 0; margin-top: 44px; border-top: 1px solid rgba(255,255,255,.1); }\n.own-shopify .sh-feature { display: grid; grid-template-columns: 80px 1fr 1.3fr; gap: 24px; align-items: start; padding: 34px 0; border-bottom: 1px solid rgba(255,255,255,.1); }\n.own-shopify .sh-feature-num { font-family: var(--f-display); font-weight: 330; font-size: 20px; color: var(--shade-40); }\n.own-shopify .sh-feature h3 { font-family: var(--f-display); font-weight: 330; font-size: clamp(22px, 2.4cqi, 36px); line-height: 1.1; margin: 0; }\n.own-shopify .sh-feature p { color: var(--shade-40); font-size: 16px; line-height: 1.6; margin: 4px 0 0; max-width: 52ch; }\n\n/* ── regions ─────────────────────────────────────────────────────────── */\n.own-shopify .sh-regions { display: grid; grid-template-columns: .9fr 1.1fr; gap: clamp(28px, 4cqi, 64px); align-items: start; }\n.own-shopify .sh-body.sh-dim { color: var(--shade-40); margin-top: 12px; }\n.own-shopify .sh-region-list { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: 1fr 1fr; gap: 0; border-top: 1px solid rgba(255,255,255,.1); }\n.own-shopify .sh-region-list li { display: flex; justify-content: space-between; gap: 12px; padding: 16px 0; border-bottom: 1px solid rgba(255,255,255,.1); }\n.own-shopify .sh-region-list:nth-child(odd) { padding-right: 18px; }\n.own-shopify .sh-region-name { font-size: 16px; font-weight: 550; }\n.own-shopify .sh-region-val { font-size: 16px; color: var(--aloe); font-family: var(--f-display); font-weight: 500; }\n\n/* ── light / transactional track ─────────────────────────────────────── */\n.own-shopify .sh-light { margin-top: var(--sec); padding: var(--sec) var(--gut); background: var(--canvas-cream); color: var(--ink); }\n.own-shopify .sh-light-head { max-width: 720px; }\n.own-shopify .sh-tiers { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; margin-top: 48px; }\n.own-shopify .sh-tier {\n  background: #fff; border: 1px solid var(--hairline-light); border-radius: 12px;\n  padding: 32px; display: flex; flex-direction: column; gap: 12px;\n  box-shadow: 0 8px 8px rgba(0,0,0,.1), 0 4px 4px rgba(0,0,0,.1), 0 2px 2px rgba(0,0,0,.1), 0 0 0 1px rgba(0,0,0,.1);\n}\n.own-shopify .sh-tier-feat { background: var(--aloe); }\n.own-shopify .sh-tier-name { font-family: var(--f-display); font-weight: 500; font-size: 28px; letter-spacing: 0.42px; }\n.own-shopify .sh-tier-price { font-family: var(--f-display); font-weight: 330; font-size: 48px; line-height: 1.14; letter-spacing: 0.01em; }\n.own-shopify .sh-tier-price small { font-family: var(--f-ui); font-weight: 500; font-size: 14px; color: var(--shade-50); }\n.own-shopify .sh-tier-list { list-style: none; margin: 6px 0 20px; padding: 0; display: grid; gap: 10px; font-size: 15px; color: var(--shade-60); }\n.own-shopify .sh-tier-list li::before { content: '—'; margin-right: 8px; color: var(--shade-40); }\n.own-shopify .sh-tier .sh-pill { margin-top: auto; width: 100%; }\n\n/* ── pistachio band card ─────────────────────────────────────────────── */\n.own-shopify .sh-band-card {\n  display: grid; grid-template-columns: 1.4fr auto; gap: 28px; align-items: center;\n  margin-top: 28px; padding: clamp(28px, 3.6cqi, 48px); border-radius: 12px;\n  background: var(--pistachio);\n}\n.own-shopify .sh-tag { display: inline-block; font-size: 12px; font-weight: 400; text-transform: uppercase; letter-spacing: 0.72px; padding: 4px 12px; border-radius: 9999px; background: var(--aloe); color: #000; margin-bottom: 14px; }\n.own-shopify .sh-band-card .sh-body { color: var(--shade-60); }\n\n/* ── comparison table ────────────────────────────────────────────────── */\n.own-shopify .sh-compare { margin-top: 44px; border: 1px solid var(--hairline-light); border-radius: 12px; overflow: hidden; background: #fff; }\n.own-shopify .sh-cmp-row { display: grid; grid-template-columns: 1.6fr 1fr 1fr 1fr; padding: 16px 24px; border-bottom: 1px solid var(--hairline-light); font-size: 15px; color: var(--shade-60); }\n.own-shopify .sh-cmp-row:last-child { border-bottom: none; }\n.own-shopify .sh-cmp-head { background: var(--canvas-cream); color: var(--ink); font-weight: 550; text-transform: uppercase; font-size: 12px; letter-spacing: 0.72px; }\n\n/* ── logos ───────────────────────────────────────────────────────────── */\n.own-shopify .sh-logos { padding-bottom: 0; }\n.own-shopify .sh-logo-wall { display: flex; flex-wrap: wrap; align-items: center; gap: clamp(24px, 5cqi, 72px); padding-top: 34px; border-top: 1px solid rgba(255,255,255,.1); }\n.own-shopify .sh-logo-wall span { font-family: var(--f-display); font-weight: 330; font-size: clamp(18px, 2cqi, 26px); letter-spacing: 0.06em; color: var(--shade-40); }\n\n/* ── footer ──────────────────────────────────────────────────────────── */\n.own-shopify .sh-footer { margin-top: var(--sec); padding: var(--sec) var(--gut) 32px; background: var(--canvas-night); }\n.own-shopify .sh-foot-grid { display: grid; grid-template-columns: 1.5fr repeat(3, 1fr); gap: 32px; }\n.own-shopify .sh-foot-brand .sh-brand { display: inline-block; margin-bottom: 14px; }\n.own-shopify .sh-foot-col { display: flex; flex-direction: column; gap: 12px; }\n.own-shopify .sh-foot-col h3 { margin: 0 0 4px; font-size: 12px; font-weight: 550; text-transform: uppercase; letter-spacing: 0.72px; color: #fff; }\n.own-shopify .sh-foot-col a { color: var(--link-cool); font-size: 15px; }\n.own-shopify .sh-foot-col a:hover { color: #fff; }\n.own-shopify .sh-foot-row { display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap; margin-top: 44px; padding-top: 22px; border-top: 1px solid rgba(255,255,255,.1); font-size: 14px; color: var(--shade-40); }\n\n/* ── responsive ──────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-shopify .sh-hero { grid-template-columns: 1fr; }\n  .own-shopify .sh-hero-vis { order: 2; min-height: 280px; }\n  .own-shopify .sh-regions { grid-template-columns: 1fr; }\n  .own-shopify .sh-tiers { grid-template-columns: 1fr 1fr; }\n  .own-shopify .sh-foot-grid { grid-template-columns: 1fr 1fr; }\n}\n@container frame (max-width: 760px) {\n  .own-shopify .sh-nav-links { display: none; }\n  .own-shopify .sh-feature { grid-template-columns: 40px 1fr; }\n  .own-shopify .sh-feature p { grid-column: 2; }\n  .own-shopify .sh-band-card { grid-template-columns: 1fr; }\n  .own-shopify .sh-cmp-row { grid-template-columns: 1.4fr 1fr 1fr; }\n  .own-shopify .sh-cmp-row span:last-child { display: none; }\n}\n@container frame (max-width: 430px) {\n  .own-shopify .sh-nav-right .sh-pill-ghost { display: none; }\n  .own-shopify .sh-tiers { grid-template-columns: 1fr; }\n  .own-shopify .sh-region-list { grid-template-columns: 1fr; }\n  .own-shopify .sh-cmp-row { grid-template-columns: 1.2fr 1fr; }\n  .own-shopify .sh-cmp-row span:nth-child(3), .own-shopify .sh-cmp-row span:last-child { display: none; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .own-shopify *, .own-shopify *::before, .own-shopify *::after { animation-duration: .001ms !important; transition-duration: .001ms !important; }\n}\n"};
/* ══ SHOPIFY — own layout behaviour for showcase.html ═════════════════════
   Registers window.OWN_LAYOUTS['shopify'].init(root). Renders feature rows,
   the region roll-up list and the pricing tiers from data. Cleanup fn. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  var FEATURES = [
    { num: '01', title: 'Live dashboards', body: 'Every site streams throughput, yield, and cost into one board that refreshes as the shift runs.' },
    { num: '02', title: 'Regional roll-ups', body: 'Aggregate site metrics into a regional view with a single query, converted to your reporting units.' },
    { num: '03', title: 'Forecasting', body: 'Model next quarter per region with confidence intervals tuned to your seasonality.' },
    { num: '04', title: 'Alerting', body: 'Route misses to the right on-call with rules matched to region and severity.' }
  ];

  var REGIONS = [
    ['Luzon', 4180], ['Visayas', 2260], ['Mindanao', 1610],
    ['Singapore', 3020], ['Sydney', 2870], ['Auckland', 1240],
    ['Osaka', 2450], ['Busan', 1980], ['Jakarta', 1760], ['Rotterdam', 2140]
  ];

  var TIERS = [
    { name: 'Starter', price: '$0', unit: '/mo', feats: ['1 region', '3 dashboards', '7-day history'], cta: 'Start free', feat: false },
    { name: 'Team', price: '$39', unit: '/mo', feats: ['5 regions', 'Unlimited dashboards', '90-day history'], cta: 'Start free trial', feat: false },
    { name: 'Business', price: '$129', unit: '/mo', feats: ['25 regions', 'Forecasting add-on', 'SSO + audit log'], cta: 'Start free trial', feat: true },
    { name: 'Enterprise', price: "Let's talk", unit: '', feats: ['Unlimited regions', 'Dedicated engineer', 'On-prem option'], cta: 'Contact sales', feat: false }
  ];

  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  OWN['shopify'] = {
    init: function (root) {
      var reduced = false;
      try { reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { /* ignore */ }

      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      var disposed = false;
      var observers = [];
      var rafs = [];
      var timeouts = [];

      function on(el, type, fn, opt) {
        if (!el) return;
        opt = Object.assign({}, opt || {});
        if (signal) opt.signal = signal;
        el.addEventListener(type, fn, opt);
      }
      function raf(fn) { var id = requestAnimationFrame(fn); rafs.push(id); return id; }
      function $(sel) { return root.querySelector(sel); }

      var grid = $('#shFeatureGrid');
      if (grid) grid.innerHTML = FEATURES.map(function (f) {
        return '<div class="sh-feature"><span class="sh-feature-num">' + f.num + '</span>'
          + '<h3>' + esc(f.title) + '</h3><p>' + esc(f.body) + '</p></div>';
      }).join('');

      var regions = $('#shRegionList');
      if (regions) regions.innerHTML = REGIONS.map(function (r) {
        return '<li><span class="sh-region-name">' + esc(r[0]) + '</span>'
          + '<span class="sh-region-val">' + r[1].toLocaleString('en-US') + '/hr</span></li>';
      }).join('');

      var tiers = $('#shTierGrid');
      if (tiers) tiers.innerHTML = TIERS.map(function (t) {
        return '<div class="sh-tier' + (t.feat ? ' sh-tier-feat' : '') + '">'
          + '<span class="sh-tier-name">' + esc(t.name) + '</span>'
          + '<span class="sh-tier-price">' + esc(t.price) + (t.unit ? ' <small>' + esc(t.unit) + '</small>' : '') + '</span>'
          + '<ul class="sh-tier-list">' + t.feats.map(function (x) { return '<li>' + esc(x) + '</li>'; }).join('') + '</ul>'
          + '<a class="sh-pill ' + (t.feat ? 'sh-pill-dark' : (t.price === '$0' ? 'sh-pill-mint' : 'sh-pill-dark')) + '" href="#">' + esc(t.cta) + '</a>'
          + '</div>';
      }).join('');

      function countUp() {
        Array.prototype.slice.call(root.querySelectorAll('.sh-region-val')).forEach(function (el) {
          var raw = (el.dataset.to || el.textContent).replace(/[^0-9]/g, '');
          var to = Number(raw) || 0;
          if (reduced) return;
          var from = Math.round(to * 0.6), start = performance.now(), dur = 900;
          el.textContent = '0/hr';
          function step(t) {
            if (disposed) return;
            var k = Math.min(1, (t - start) / dur), e = 1 - Math.pow(1 - k, 3);
            el.textContent = Math.round(from + (to - from) * e).toLocaleString('en-US') + '/hr';
            if (k < 1) raf(step);
          }
          raf(step);
        });
      }
      Array.prototype.slice.call(root.querySelectorAll('.sh-region-val')).forEach(function (el) {
        el.dataset.to = (el.textContent.match(/[0-9,]+/) || ['0'])[0];
      });

      var io = null;
      if (!reduced && typeof IntersectionObserver !== 'undefined') {
        io = new IntersectionObserver(function (ents) {
          ents.forEach(function (en) {
            if (en.isIntersecting) { countUp(); io.unobserve(en.target); }
          });
        }, { threshold: 0.25 });
        var list = $('#shRegionList');
        if (list) { observers.push(io); io.observe(list); }
      }

      return function cleanup() {
        disposed = true;
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
        rafs.forEach(function (id) { cancelAnimationFrame(id); });
        timeouts.forEach(function (id) { clearTimeout(id); });
        observers.forEach(function (o) { try { o.disconnect(); } catch (e) { /* ignore */ } });
      };
    }
  };
})();
